import json
from pathlib import Path
for p in ['/app/benchmark/task_input.json','/app/benchmark/source_data.json']:
    print('\n---',p,'---')
    data=json.loads(Path(p).read_text())
    if p.endswith('task_input.json'):
        print(json.dumps(data, indent=2))
    else:
        print('keys:', data.keys())
        def summarize(x, indent=0):
            if isinstance(x, dict):
                for k,v in x.items():
                    print(' '*indent+k+':', type(v).__name__, (len(v) if hasattr(v,'__len__') else ''))
                    summarize(v, indent+2)
                    break
            elif isinstance(x, list):
                print(' '*indent+'len', len(x))
                if x: print(' '*indent+'first', json.dumps(x[0], indent=2)[:1200])
        summarize(data)
print('\n--- brief ---')
print(Path('/app/benchmark/source_brief.md').read_text()[:5000])
